// Золотой набор: вопрос -> id фрагмента, где лежит ответ (разметил человек).
// retrieved: что вернул поиск, от лучшего к худшему (иллюстративные данные).
const golden = [
  { q: "Как вернуть товар?",         gold: "c12", retrieved: ["c12", "c40", "c07", "c33", "c90", "c02", "c18", "c61"] },
  { q: "Сколько идёт доставка?",     gold: "c55", retrieved: ["c54", "c55", "c91", "c10", "c03", "c77", "c21", "c08"] },
  { q: "Что значит ошибка 4017?",    gold: "c88", retrieved: ["c89", "c13", "c47", "c88", "c05", "c66", "c30", "c19"] },
  { q: "Можно ли платить в рублях?", gold: "c23", retrieved: ["c23", "c24", "c70", "c11", "c02", "c95", "c44", "c31"] },
  { q: "Где скачать счёт?",          gold: "c71", retrieved: ["c15", "c16", "c71", "c09", "c52", "c38", "c27", "c64"] },
];

const recallAtK = (k) =>
  golden.filter((g) => g.retrieved.slice(0, k).includes(g.gold)).length / golden.length;

for (const k of [1, 3, 5, 8]) console.log("recall@" + k + " = " + recallAtK(k));
// recall@1 = 0.4
// recall@3 = 0.8
