async function rerank(query, candidates, topK) {
  const res = await fetch("https://api.voyageai.com/v1/rerank", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + process.env.VOYAGE_API_KEY,
    },
    body: JSON.stringify({
      model: "rerank-2.5",
      query,
      documents: candidates.map((c) => c.text),
      top_k: topK,
    }),
  });
  const json = await res.json();
  // data уже отсортирован по relevance_score по убыванию;
  // index указывает на позицию документа в исходном массиве
  return json.data.map((r) => ({ ...candidates[r.index], score: r.relevance_score }));
}

